    #       }
    #     ],
    #     target_db_instance_class: "TargetDBInstanceClass",
    #     upgrade_target_storage_config: false,
    #     target_iops: 1,
    #     target_storage_type: "TargetStorageType",
    #     target_allocated_storage: 1,
