    #           status: "SwitchoverDetailStatus"
    #         }
    #       ],
    #       tasks: [
    #         {
    #           name: "BlueGreenDeploymentTaskName",
    #           status: "BlueGreenDeploymentTaskStatus"
    #         }
    #       ],
    #       status: "BlueGreenDeploymentStatus",
    #       status_details: "BlueGreenDeploymentStatusDetails",
    #       create_time: Time.now,
    #       delete_time: Time.now,
    #       tag_list: [
    #         {
    #           key: "String",
    #           value: "String"
    #         }
    #       ]
    #     }
    #   }
    # @return [Types::CreateBlueGreenDeploymentResponse]
    def create_blue_green_deployment(params = {}, options = {})
      request = build_request(:create_blue_green_deployment, params)
      request.send_request(options)
    end

