    #       tag_list: [
    #         {
    #           key: "String",
    #           value: "String"
    #         }
    #       ]
    #     }
    #   }
    # @return [Types::FailoverGlobalClusterResult]
    def failover_global_cluster(params = {}, options = {})
      request = build_request(:failover_global_cluster, params)
      request.send_request(options)
    end

