    #       port: 1,
    #       master_username: "String",
    #       db_cluster_option_group_memberships: [
    #         {
    #           db_cluster_option_group_name: "String",
    #           status: "String"
    #         }
    #       ],
    #       preferred_backup_window: "String",
    #       preferred_maintenance_window: "String",
    #       replication_source_identifier: "String",
    #       read_replica_identifiers: ["String"],
    #       status_infos: [
    #         {
    #           status_type: "String",
    #           normal: false,
    #           status: "String",
    #           message: "String"
    #         }
    #       ],
    #       db_cluster_members: [
    #         {
    #           db_instance_identifier: "String",
    #           is_cluster_writer: false,
    #           db_cluster_parameter_group_status: "String",
    #           promotion_tier: 1
    #         }
    #       ],
    #       vpc_security_groups: [
    #         {
    #           vpc_security_group_id: "String",
    #           status: "String"
    #         }
    #       ],
    #       hosted_zone_id: "String",
    #       storage_encrypted: false,
    #       kms_key_id: "String",
    #       db_cluster_resource_id: "String",
    #       db_cluster_arn: "String",
    #       associated_roles: [
    #         {
    #           role_arn: "String",
    #           status: "String",
    #           feature_name: "String"
    #         }
    #       ],
    #       iam_database_authentication_enabled: false,
    #       clone_group_id: "String",
    #       cluster_create_time: Time.now,
    #       earliest_backtrack_time: Time.now,
    #       backtrack_window: 1,
    #       backtrack_consumed_change_records: 1,
